  (demo.u('org:bean-culture'), demo.u('bc:thread:smith'), 'demo-smith-0', 'inbound', 'emma.smith@example.com', 'Emma Smith', array['info@beanculture.com.au']::text[], 'Coffee cart for our wedding', 'Hi! We''re getting married and would love a coffee cart for the post-ceremony drinks. Around 80 guests. Do you do oat milk and chai?', 'Hi! We''re getting married and would love a coffee cart for the post-ceremony drinks. Around 80 guests. Do you do oat milk and chai?', demo.ago(172800), true, null),
  (demo.u('org:bean-culture'), demo.u('bc:thread:smith'), 'demo-smith-1', 'outbound', 'info@beanculture.com.au', 'Jess Harper', array['emma.smith@example.com']::text[], 'Re: Coffee cart for our wedding', 'Hi Emma, congratulations! We''d love to be part of it. Yes to oat milk and chai. I''ll put a quote together.', 'Hi Emma, congratulations! We''d love to be part of it. Yes to oat milk and chai. I''ll put a quote together.', demo.ago(171360), true, demo.u('user:jess')),
